/**
 * Acceptance check for PR #1947: collapsible quick-search bar for in-session find.
 * 
 * Verifies the public API of the new quick-search feature:
 * - `isFindShortcut` correctly detects Ctrl/Cmd+F
 * - `formatCount` formats n/m counts correctly
 * - `QuickSearchBar` component exists and has the expected props interface
 */

import { describe, it, expect } from "vitest";
import { isFindShortcut, formatCount } from "~/reader/quick-search";

describe("quick-search public API", () => {
  describe("isFindShortcut", () => {
    it("returns true for Ctrl+F", () => {
      const e = new KeyboardEvent("keydown", { key: "f", ctrlKey: true });
      expect(isFindShortcut(e)).toBe(true);
    });

    it("returns true for Cmd+F (meta)", () => {
      const e = new KeyboardEvent("keydown", { key: "F", metaKey: true });
      expect(isFindShortcut(e)).toBe(true);
    });

    it("returns false for plain F without modifier", () => {
      const e = new KeyboardEvent("keydown", { key: "f" });
      expect(isFindShortcut(e)).toBe(false);
    });

    it("returns false for Ctrl+Shift+F", () => {
      const e = new KeyboardEvent("keydown", { key: "f", ctrlKey: true, shiftKey: true });
      expect(isFindShortcut(e)).toBe(false);
    });

    it("returns false for Ctrl+Alt+F", () => {
      const e = new KeyboardEvent("keydown", { key: "f", ctrlKey: true, altKey: true });
      expect(isFindShortcut(e)).toBe(false);
    });

    it("returns false for non-f keys with Ctrl", () => {
      const e = new KeyboardEvent("keydown", { key: "a", ctrlKey: true });
      expect(isFindShortcut(e)).toBe(false);
    });
  });

  describe("formatCount", () => {
    it("formats n/m when not scanning (1-based index)", () => {
      // index is 0-based internally, so index=0 means first hit = "1"
      expect(formatCount(0, 10, false)).toBe("1/10");
      expect(formatCount(4, 10, false)).toBe("5/10");
    });

    it("shows ellipsis when scanning", () => {
      expect(formatCount(0, 10, true)).toBe("…/10");
      expect(formatCount(99, 100, true)).toBe("…/100");
    });

    it("handles zero total", () => {
      expect(formatCount(0, 0, false)).toBe("1/0");
    });
  });
});
